fn binary_search(a: &[i32], key: i32) -> usize {
    // We maintain a search window [low, high).
    // Invariant:
    //   - all indices < low have a[i] < key
    //   - all indices >= high have a[i] >= key
    let mut low = 0;
    let mut high = a.len();

    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < key {
            // mid is still < key, so the insertion point is to the right of mid
            low = mid + 1;
        } else {
            // a[mid] >= key, so the insertion point is at or before mid
            high = mid;
        }
    }

    // At loop exit, low == high and is the first index at which a[index] >= key,
    // or a.len() if all elements are < key.
    low
}

